import { Track } from "./types";

export const aspTrack: Track = {
  id: "asp",
  title: "ASP",
  titleBn: "এএসপি",
  tagline: "Learn classic Microsoft server-side web development",
  taglineBn: "ক্লাসিক মাইক্রোসফট সার্ভার-সাইড ওয়েব ডেভেলপমেন্ট শিখুন",
  icon: "🖥️",
  colorVar: "--asp-color",
  brandColor: "#0066CC",
  glowColor: "rgba(0,102,204,0.3)",
  totalChapters: 60,
  estimatedHours: 100,
  chapters: [
  { id:"c1", title:"Introduction to ASP", titleBn:"ASP ভূমিকা", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"What is Active Server Pages?","content":"ASP is Microsoft's server-side scripting engine. ASP files contain HTML mixed with server-side scripts processed by IIS before sending to browser."},{"id":"s2","type":"lesson","title":"How ASP Works","content":"Browser requests .asp file → IIS routes to asp.dll → scripts execute → pure HTML returned. Server-side code is invisible to clients."},{"id":"s3","type":"lesson","title":"ASP vs ASP.NET","content":"Classic ASP uses interpreted VBScript/JScript with inline code. ASP.NET is compiled, supports MVC, Web Forms, and multiple languages."},{"id":"s4","type":"quiz","question":"What processes ASP files?","options":["Browser","IIS","Apache","Node.js"],"correct":1,"explanation":"IIS processes ASP files server-side."},{"id":"s5","type":"exercise","title":"Setup ASP Environment","description":"Enable IIS and ASP on Windows, create a test .asp file with Response.Write, and verify it works in browser."}] },
  { id:"c2", title:"ASP Syntax and Structure", titleBn:"ASP সিনট্যাক্স এবং গঠন", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"ASP Delimiters","content":"<% %> encloses ASP code. <%= %> outputs values. Mix HTML and ASP freely. Code outside delimiters is sent as HTML."},{"id":"s2","type":"lesson","title":"Directives","content":"<%@ Language=VBScript %>, <%@ EnableSessionState=True %>, <%@ LCID=1033 %> control page processing. Placed at top of file."},{"id":"s3","type":"lesson","title":"Comments","content":"Use REM or single quote (') for comments. Comments are not sent to client. Good for documenting complex logic."},{"id":"s4","type":"quiz","question":"Which delimiter outputs a value directly?","options":["<%","<%=","<%@","<%="],"correct":1,"explanation":"<%= expression %> outputs value directly to response."},{"id":"s5","type":"exercise","title":"Write First ASP Page","description":"Create an ASP page that displays current date, time, and a personalized greeting using server variables."}] },
  { id:"c3", title:"VBScript Data Types", titleBn:"VBScript ডেটা টাইপ", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"Variant Data Type","content":"VBScript has one data type: Variant. Can hold numeric, string, date, object, or array. VarType() checks subtype at runtime."},{"id":"s2","type":"lesson","title":"Numeric Subtypes","content":"vbInteger (-32768 to 32767), vbLong (-2^31 to 2^31-1), vbSingle (floating), vbDouble (double precision), vbCurrency, vbByte."},{"id":"s3","type":"lesson","title":"String and Date Subtypes","content":"vbString for text, vbDate for dates (#1/1/2024#), vbBoolean (True/False), vbEmpty (uninitialized), vbNull (no valid data)."},{"id":"s4","type":"quiz","question":"What does VarType return?","options":["Data type name","Data type number","Variable name","Variable value"],"correct":1,"explanation":"VarType returns a numeric code for the subtype."},{"id":"s5","type":"exercise","title":"Type Conversion","description":"Create variables of different subtypes, convert between them using CInt, CStr, CDate, CDbl, and display results."}] },
  { id:"c4", title:"Variables and Constants", titleBn:"ভেরিয়েবল এবং কনস্ট্যান্ট", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"Declaring Variables","content":"Dim variableName declares a variable. Option Explicit forces declaration. Multiple vars: Dim x, y, z. Array: Dim arr(5). Dynamic array: ReDim arr(10)."},{"id":"s2","type":"lesson","title":"Variable Scope","content":"Script-level (outside procedures), Procedure-level (inside Sub/Function). Use Public and Private for explicit scoping. Global variables via Application/Session."},{"id":"s3","type":"lesson","title":"Constants","content":"Const PI = 3.14159 defines a constant. Cannot change value later. Built-in constants: vbTab, vbCrLf, vbNewLine, vbNullString. Named for readability."},{"id":"s4","type":"quiz","question":"How do you force variable declaration?","options":["Dim","Option Explicit","Public","Private"],"correct":1,"explanation":"Option Explicit forces all variables to be declared before use."},{"id":"s5","type":"exercise","title":"Working with Variables","description":"Declare variables with different subtypes, use arrays, demonstrate scope by calling procedures that access script-level variables."}] },
  { id:"c5", title:"Operators and Expressions", titleBn:"অপারেটর এবং এক্সপ্রেশন", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"Arithmetic Operators","content":"+(addition), -(subtraction), *(multiplication), /(division), \\(integer division), Mod(modulus), ^(exponentiation). Integer division rounds down."},{"id":"s2","type":"lesson","title":"Comparison Operators","content":"=(equal), <>(not equal), <(less), >(greater), <=, >=. Compare numeric, string, or date values. Returns Boolean True/False."},{"id":"s3","type":"lesson","title":"Logical Operators","content":"And(both true), Or(either true), Not(negation), Xor(exclusive or), Eqv(equivalence), Imp(implication). Short-circuit not supported."},{"id":"s4","type":"quiz","question":"Which operator performs integer division?","options":["/","\\","Mod","^"],"correct":1,"explanation":"Backslash (\\) performs integer division returning integer result."},{"id":"s5","type":"exercise","title":"Write Expressions","description":"Write arithmetic, comparison, and logical expressions. Demonstrate operator precedence with compound expressions."}] },
  { id:"c6", title:"Conditional Statements", titleBn:"শর্তাধীন বিবৃতি", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"If...Then...Else","content":"Basic: If condition Then. ElseIf for multiple conditions. Else for fallback. End If closes block. Single-line: If x>y Then Response.Write x."},{"id":"s2","type":"lesson","title":"Select Case","content":"Select Case variable: Case value1, Case value2, Case Else. Cleaner than multiple ElseIf. Supports Case Is(comparison) and Case Else."},{"id":"s3","type":"lesson","title":"Nested Conditionals","content":"Conditions inside conditions. Use indentation for readability. Avoid deep nesting—consider Select Case or extracting to Function."},{"id":"s4","type":"quiz","question":"Which statement is better for multiple conditions?","options":["If...Then","Select Case","While","For"],"correct":1,"explanation":"Select Case is cleaner than multiple ElseIf for single variable checks."},{"id":"s5","type":"exercise","title":"Grade Calculator","description":"Write a program that takes a numeric score and returns letter grade (A-F) using Select Case. Display appropriate message."}] },
  { id:"c7", title:"Loop Structures", titleBn:"লুপ স্ট্রাকচার", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"For...Next","content":"For i = 1 To 10 Step 1: statements: Next. Step can be negative. Use Exit For to break early. Use nested loops for multi-dimensional arrays."},{"id":"s2","type":"lesson","title":"Do While...Loop","content":"Do While condition: statements: Loop. Executes while condition is True. Exit Do breaks. Do...Loop While runs at least once."},{"id":"s3","type":"lesson","title":"For Each...Next","content":"Iterates through collections and arrays. For Each item In collection: statements: Next. Cannot modify collection during iteration. Safer than index loops."},{"id":"s4","type":"quiz","question":"Which loop runs at least once?","options":["For...Next","Do While...Loop","Do...Loop While","For Each"],"correct":2,"explanation":"Do...Loop While checks condition after execution, guaranteeing at least one iteration."},{"id":"s5","type":"exercise","title":"Loop Practice","description":"Use For loop to print 1-10, Do While to sum user input until zero, For Each to iterate array items."}] },
  { id:"c8", title:"Arrays in VBScript", titleBn:"VBScript-এ অ্যারে", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"Fixed Arrays","content":"Dim arr(5) creates 0-5 (6 elements). Access: arr(index). LBound returns lowest index, UBound returns highest. Multi-dimensional: Dim matrix(3,3)."},{"id":"s2","type":"lesson","title":"Dynamic Arrays","content":"Dim arr(): ReDim arr(10): ReDim Preserve arr(20) preserves existing values. Erase arr clears array. Dynamic arrays save memory."},{"id":"s3","type":"lesson","title":"Array Functions","content":"Array(1,2,3) creates populated array. Join(arr, \",\") converts to string. Split(\"a,b,c\", \",\") converts string to array. IsArray checks type."},{"id":"s4","type":"quiz","question":"Which keyword preserves array contents when resizing?","options":["ReDim","Preserve","Dim","Erase"],"correct":1,"explanation":"ReDim Preserve resizes array while keeping existing values."},{"id":"s5","type":"exercise","title":"Array Manipulation","description":"Create fixed array of 5 names, dynamic array with ReDim Preserve, demonstrate Split/Join, and iterate with For Each."}] },
  { id:"c9", title:"Procedures: Sub and Function", titleBn:"প্রসিডিওর: সাব এবং ফাংশন", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"Sub Procedures","content":"Sub Name(args): ... End Sub. Performs actions, no return value. Call keyword optional. Arguments passed ByRef (default) or ByVal."},{"id":"s2","type":"lesson","title":"Functions","content":"Function Name(args): Name = value: End Function. Returns value by assigning to function name. Can return any Variant subtype."},{"id":"s3","type":"lesson","title":"Parameter Passing","content":"ByRef passes reference—changes affect original variable. ByVal passes copy—original unchanged. Use ByVal for primitives, ByRef for objects."},{"id":"s4","type":"quiz","question":"How does a Function return a value?","options":["Return keyword","Exit Function","Assign to function name","Response.Write"],"correct":2,"explanation":"Assign value to function name: FunctionName = value."},{"id":"s5","type":"exercise","title":"Create Utility Functions","description":"Write functions: CalculateArea(radius), IsValidEmail(email), FormatDate(date). Create Sub to display formatted output."}] },
  { id:"c10", title:"Built-in Functions", titleBn:"বিল্ট-ইন ফাংশন", part:"ASP Fundamentals", sections:[{"id":"s1","type":"lesson","title":"String Functions","content":"Len(str), Mid(str,start,len), Left(str,len), Right(str,len), InStr(str,substr), Replace(str,old,new), UCase, LCase, Trim, LTrim, RTrim."},{"id":"s2","type":"lesson","title":"Date and Time Functions","content":"Now, Date, Time, DateAdd(interval,num,date), DateDiff(interval,d1,d2), DatePart, FormatDateTime, Month, Year, Day, WeekDay."},{"id":"s3","type":"lesson","title":"Math and Conversion","content":"Int, Fix, Round, Abs, Sqr, Rnd (random). CInt, CLng, CSng, CDbl, CStr, CDate, CBool, CCur. FormatCurrency, FormatNumber, FormatPercent."},{"id":"s4","type":"quiz","question":"Which function returns portion of a string?","options":["Mid","Len","InStr","Replace"],"correct":0,"explanation":"Mid(str, start, length) returns a specified portion of a string."},{"id":"s5","type":"exercise","title":"Function Practice","description":"Use string functions to parse a full name, date functions to calculate age from birthday, math functions to generate random numbers."}] },
  { id:"c11", title:"Error Handling", titleBn:"এরর হ্যান্ডলিং", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"On Error Resume Next","content":"On Error Resume Next ignores runtime errors. Check Err.Number after risky operations. If Err.Number <> 0 Then handle error."},{"id":"s2","type":"lesson","title":"Err Object","content":"Err.Number(error code), Err.Description(message), Err.Source(source name), Err.HelpFile, Err.HelpContext. Err.Clear resets. Err.Raise generates errors."},{"id":"s3","type":"lesson","title":"Error Handling Strategy","content":"Set On Error Resume Next before risky code. Check Err after each operation. Use centralized error handler function. Log errors for debugging."},{"id":"s4","type":"quiz","question":"How do you reset the Err object?","options":["Err.Reset","Err.Clear","Err.Raise","Err.Handle"],"correct":1,"explanation":"Err.Clear resets the Err object after an error occurs."},{"id":"s5","type":"exercise","title":"Error Handling Demo","description":"Write code that causes division by zero, handle with On Error Resume Next, display Err.Description, and log to application variable."}] },
  { id:"c12", title:"String Manipulation", titleBn:"স্ট্রিং ম্যানিপুলেশন", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"String Comparison","content":"StrComp(str1, str2, compareMethod). vbBinaryCompare(0) case-sensitive, vbTextCompare(1) case-insensitive. Returns -1(str1<str2), 0(equal), 1(str1>str2)."},{"id":"s2","type":"lesson","title":"String Building","content":"& operator concatenates strings. StringBuilder approach for large strings: store in array then Join. Avoid repeated & in loops."},{"id":"s3","type":"lesson","title":"String Formatting","content":"Pad strings: Space(n), String(n,char). FormatNumber, FormatCurrency, FormatDateTime. Align with tab character vbTab. Line breaks: vbCrLf."},{"id":"s4","type":"quiz","question":"Which comparison is case-insensitive?","options":["vbBinaryCompare","vbTextCompare","vbCaseCompare","vbIgnoreCase"],"correct":1,"explanation":"vbTextCompare performs case-insensitive string comparison."},{"id":"s5","type":"exercise","title":"String Processing","description":"Write functions: ReverseString, CountWords(str), RemoveVowels(str), and IsPalindrome(str) using string manipulation functions."}] },
  { id:"c13", title:"File System Operations", titleBn:"ফাইল সিস্টেম অপারেশন", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"FileSystemObject","content":"Create via Server.CreateObject(\"Scripting.FileSystemObject\"). Provides methods for drives, folders, files. Powerful but security sensitive."},{"id":"s2","type":"lesson","title":"Reading and Writing Files","content":"OpenTextFile(file, iomode, create). IOMode: ForReading(1), ForWriting(2), ForAppending(8). Methods: ReadAll, ReadLine, Write, WriteLine, Close."},{"id":"s3","type":"lesson","title":"Folder Operations","content":"CreateFolder, DeleteFolder, FolderExists, GetFolder, GetParentFolderName. CopyFolder source, dest. MoveFolder. Enumerate files in folder."},{"id":"s4","type":"quiz","question":"Which mode opens a file for appending?","options":["ForReading","ForWriting","ForAppending","ForModifying"],"correct":2,"explanation":"ForAppending(8) opens file for appending without overwriting existing content."},{"id":"s5","type":"exercise","title":"File Manager","description":"Create functions to read a text file line by line, write user input to a log file, check if file exists, and list files in a directory."}] },
  { id:"c14", title:"Dictionary Object", titleBn:"ডিকশনারি অবজেক্ট", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"Creating Dictionary","content":"Set dict = CreateObject(\"Scripting.Dictionary\"). Key-value data structure. Keys must be unique. Values can be any type including arrays and objects."},{"id":"s2","type":"lesson","title":"Dictionary Methods","content":"Add key, item: dict.Add \"name\", \"value\". Exists(key) checks existence. Remove(key) deletes entry. Items returns array of all values. Keys returns array."},{"id":"s3","type":"lesson","title":"Dictionary Properties","content":"Count(number of items), Item(key)(read/write), Key(key) rename key, CompareMode(vbBinaryCompare/vbTextCompare for key matching)."},{"id":"s4","type":"quiz","question":"What happens when adding duplicate key to Dictionary?","options":["Overwrites","Error","Appends","Ignores"],"correct":1,"explanation":"Adding a duplicate key causes a runtime error. Use Exists() to check first."},{"id":"s5","type":"exercise","title":"Dictionary Practice","description":"Use Dictionary to store student grades(key=name, value=grade). Add, remove, update entries. Display all students and calculate average grade."}] },
  { id:"c15", title:"Regular Expressions", titleBn:"রেগুলার এক্সপ্রেশন", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"RegExp Object","content":"New RegExp creates regex object. Properties: Pattern(regex pattern), IgnoreCase(boolean), Global(find all matches). Methods: Test, Execute, Replace."},{"id":"s2","type":"lesson","title":"Pattern Syntax","content":".(any char), *(0+), +(1+), ?(0-1), ^(start), $(end), \\d(digit), \\w(word char), [abc](set), [^abc](negation), (group), |(or)."},{"id":"s3","type":"lesson","title":"Practical Patterns","content":"Email: ^[\\w.-]+@[\\w.-]+\\.\\w+$. Phone: ^\\d{3}-\\d{3}-\\d{4}$. URL, IP address, date formats. Test with RegExp.Test method."},{"id":"s4","type":"quiz","question":"Which RegExp property enables global matching?","options":["IgnoreCase","Global","Pattern","MultiLine"],"correct":1,"explanation":"Global=True finds all matches, not just the first one."},{"id":"s5","type":"exercise","title":"Regex Validation","description":"Write validation functions using RegExp for: email, phone number, ZIP code, and URL. Test with valid and invalid inputs."}] },
  { id:"c16", title:"Classes with VBScript 5", titleBn:"VBScript 5 দিয়ে ক্লাস", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"Class Definition","content":"Class ClassName: Properties: Public varName: Methods: Sub/Functions. Private members with Private keyword. Property Get/Let for controlled access."},{"id":"s2","type":"lesson","title":"Constructor and Destructor","content":"Class_Initialize runs on creation(Set obj = New ClassName). Class_Terminate runs on destruction(Set obj = Nothing). Initialize for setup code."},{"id":"s3","type":"lesson","title":"Encapsulation","content":"Private internalState: Public Property Get Name(): Name = internalState: End Property: Public Property Let Name(val): internalState = val: End Property."},{"id":"s4","type":"quiz","question":"Which method runs when object is destroyed?","options":["Class_Initialize","Class_Terminate","Class_Destroy","Class_End"],"correct":1,"explanation":"Class_Terminate runs when object is set to Nothing or goes out of scope."},{"id":"s5","type":"exercise","title":"Build a Class","description":"Create a BankAccount class with properties(AccountNumber, Balance), methods(Deposit, Withdraw), and private state validation."}] },
  { id:"c17", title:"COM Components", titleBn:"কম্পোনেন্ট অবজেক্ট মডেল", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"Creating COM Objects","content":"Server.CreateObject(\"ProgID\") instantiates COM components. Common examples: ADODB.Connection, Scripting.FileSystemObject, MSXML2.ServerXMLHTTP."},{"id":"s2","type":"lesson","title":"Object Lifecycle","content":"Set obj = CreateObject(...): Use obj: Set obj = Nothing(immediately release). Objects hold resources—release promptly. Reference counting determines lifetime."},{"id":"s3","type":"lesson","title":"Registering Components","content":"regsvr32.exe registers/unregisters COM DLLs. Run from admin command prompt. 64-bit vs 32-bit component matching matters. DCOM for remote components."},{"id":"s4","type":"quiz","question":"How do you release a COM object?","options":["obj.Release()","Set obj = Nothing","obj.Close()","obj.Dispose()"],"correct":1,"explanation":"Set obj = Nothing releases reference and decrements reference count."},{"id":"s5","type":"exercise","title":"COM Objects Practice","description":"Create FileSystemObject to read file, Dictionary for in-memory cache, and MSXML2.XMLHTTP to fetch data from an API endpoint."}] },
  { id:"c18", title:"Sending Emails from ASP", titleBn:"ASP থেকে ইমেল পাঠানো", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"CDONTS/CDO Library","content":"CDONTS.NewMail (older) or CDO.Message (newer, IIS SMTP). Set objMail = CreateObject(\"CDO.Message\"). Configure with Configuration.Fields."},{"id":"s2","type":"lesson","title":"Email Configuration","content":"SMTP server, port(25/587), authentication, SSL. Schema: \"http://schemas.microsoft.com/cdo/configuration/smtpserver\". Set fields, then Fields.Update."},{"id":"s3","type":"lesson","title":"Sending Email","content":"objMail.From = \"sender@domain.com\": objMail.To = \"recipient@domain.com\": objMail.Subject = \"Subject\": objMail.TextBody = \"Body\". objMail.Send. HTML email: objMail.HTMLBody."},{"id":"s4","type":"quiz","question":"Which object sends email in modern ASP?","options":["CDONTS.NewMail","CDO.Message","SMTP.Mail","ASPEmail"],"correct":1,"explanation":"CDO.Message is the newer email object using IIS SMTP service."},{"id":"s5","type":"exercise","title":"Mail Form","description":"Create a contact form: name, email, subject, message. Server-side validation, send email with CDO.Message, display success/error to user."}] },
  { id:"c19", title:"XML and ASP", titleBn:"এএসপি এবং এক্সএমএল", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"XML DOM Parser","content":"CreateObject(\"MSXML2.DOMDocument\"). Load XML from string(.loadXML) or file(.load). Parse: SelectSingleNode, SelectNodes with XPath. Access: .text, .nodeName."},{"id":"s2","type":"lesson","title":"XMLHTTP Requests","content":"CreateObject(\"MSXML2.ServerXMLHTTP\"). Open(method,url,async), Send, .responseText contains response. Use for REST APIs. Set timeouts."},{"id":"s3","type":"lesson","title":"Generating XML","content":"Build XML string with Response.Write or MSXML2.DOMDocument. Set ContentType=\"text/xml\". Use for AJAX endpoints, RSS feeds, sitemaps."},{"id":"s4","type":"quiz","question":"Which object is used for HTTP requests?","options":["XMLHTTP","ServerXMLHTTP","DOMDocument","XMLParser"],"correct":1,"explanation":"ServerXMLHTTP is the server-side object for making HTTP requests from ASP."},{"id":"s5","type":"exercise","title":"XML Data Feed","description":"Create an ASP page that reads XML data file, parses with DOMDocument, displays records in HTML table. Add stylesheet for formatting."}] },
  { id:"c20", title:"Performance Optimization", titleBn:"পারফরম্যান্স অপ্টিমাইজেশন", part:"VBScript & Procedures", sections:[{"id":"s1","type":"lesson","title":"Caching Strategies","content":"Response.Expires and Response.CacheControl set browser caching. Application variables cache data in memory. Query result caching with Dictionary."},{"id":"s2","type":"lesson","title":"Query Optimization","content":"Use stored procedures instead of inline SQL. Limit SELECT columns. Use WHERE clauses to reduce rows. Proper indexing. Set Recordset.CacheSize."},{"id":"s3","type":"lesson","title":"Code Optimization","content":"Minimize Response.Write calls(accumulate string). Use Option Explicit. Avoid Session variables unless needed. Turn off Session state if not used. Use early binding."},{"id":"s4","type":"quiz","question":"Which setting disables Session state for a page?","options":["@EnableSessionState=True","@EnableSessionState=False","Session.Abandon","Session.Timeout=0"],"correct":1,"explanation":"<%@ EnableSessionState=False %> disables session for the page, improving performance."},{"id":"s5","type":"exercise","title":"Optimize ASP Page","description":"Take a slow ASP page, apply caching strategies, optimize database queries, implement output buffering, and measure performance improvement."}] },
  { id:"c21", title:"Response Object Deep Dive", titleBn:"রেসপন্স অবজেক্ট", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Response Properties","content":"Buffer(True/False), CacheControl(private/public), Charset(UTF-8), ContentType(MIME type), Expires(minutes), IsClientConnected, Status(HTTP code)."},{"id":"s2","type":"lesson","title":"Response Methods","content":"Write(text), Redirect(url), End, Clear, Flush, BinaryWrite(data), AppendToLog(entry). AddHeader(name, value) for custom headers. Pics(rating) for content ratings."},{"id":"s3","type":"lesson","title":"Response Cookies Collection","content":"Set multiple cookies: Response.Cookies(\"prefs\")(\"theme\")=\"dark\". Cookie properties: Expires, Domain, Path, Secure, HasKeys, HttpOnly."},{"id":"s4","type":"quiz","question":"What does Response.Buffer do?","options":["Buffers output before sending","Sets cache duration","Controls compression","Manages cookies"],"correct":0,"explanation":"Response.Buffer=True holds output in buffer until Flush or page completes."},{"id":"s5","type":"exercise","title":"Response Object Mastery","description":"Create page that uses Response.Buffer, writes HTML table, uses IsClientConnected to check, and streams progressively with Flush."}] },
  { id:"c22", title:"Request Object Deep Dive", titleBn:"রিকোয়েস্ট অবজেক্ট", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Request Collections","content":"Form(POST), QueryString(GET), Cookies, ServerVariables, ClientCertificate. TotalBytes(byte count), BinaryRead for raw data. Syntax: Request.Collection(\"key\")."},{"id":"s2","type":"lesson","title":"ServerVariables Collection","content":"REMOTE_ADDR(client IP), HTTP_USER_AGENT(browser), REQUEST_METHOD(GET/POST), SERVER_NAME, QUERY_STRING, PATH_INFO, CONTENT_TYPE, HTTPS(on/off)."},{"id":"s3","type":"lesson","title":"Binary Data Handling","content":"Request.TotalBytes returns upload size. Request.BinaryRead reads raw bytes. Use for file uploads without COM components. Parse multipart form data."},{"id":"s4","type":"quiz","question":"Which collection contains browser information?","options":["Form","QueryString","ServerVariables","Cookies"],"correct":2,"explanation":"HTTP_USER_AGENT in ServerVariables contains browser user-agent string."},{"id":"s5","type":"exercise","title":"Request Inspector","description":"Build a page that displays all ServerVariables in a table, shows form/query string params, and echoes uploaded file details."}] },
  { id:"c23", title:"Server Object Deep Dive", titleBn:"সার্ভার অবজেক্ট", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Server Methods","content":"CreateObject(progID), HTMLEncode(str), URLEncode(str), MapPath(virtualPath), Execute(path), Transfer(path), GetLastError(). ScriptTimeout property."},{"id":"s2","type":"lesson","title":"HTML and URL Encoding","content":"HTMLEncode converts < > & \" to &lt; &gt; &amp; &quot;. Prevents XSS. URLEncode converts spaces to +, special chars to %XX. Essential for safe URL construction."},{"id":"s3","type":"lesson","title":"Server.Execute vs Transfer","content":"Execute processes sub-page and returns to caller. Transfer stops current page and processes new page(browser URL unchanged). Both avoid round trip."},{"id":"s4","type":"quiz","question":"Which method converts virtual to physical path?","options":["MapPath","URLEncode","HTMLEncode","CreateObject"],"correct":0,"explanation":"Server.MapPath converts virtual paths(/) to physical file system paths."},{"id":"s5","type":"exercise","title":"Server Utilities","description":"Create functions: sanitizeHTML(str) using HTMLEncode, buildSafeURL(params) using URLEncode, and include template using Server.Execute."}] },
  { id:"c24", title:"Session Object Deep Dive", titleBn:"সেশন অবজেক্ট", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Session Configuration","content":"Session.Timeout(minutes), Session.SessionID(unique per session), Session.LCID(locale), Session.CodePage(encoding). Configure in Global.asa or IIS."},{"id":"s2","type":"lesson","title":"Session Contents Collection","content":"Session.Contents holds all session variables. Count property. Remove(key) removes one. RemoveAll() clears all. Loop: For Each v In Session.Contents."},{"id":"s3","type":"lesson","title":"Session State Modes","content":"In-Process(default, fastest, lost on restart), StateServer(out-of-process, shared across web farm), SQLServer(persistent, reliable). Configure in IIS."},{"id":"s4","type":"quiz","question":"What happens when Session.Abandon is called?","options":["Resets timeout","Clears variables","Ends session","All of above"],"correct":3,"explanation":"Session.Abandon queues session for deletion, all variables are lost."},{"id":"s5","type":"exercise","title":"Session Manager","description":"Build admin page that displays all active sessions, shows SessionID, timeout, variables. Allow admin to clear specific sessions."}] },
  { id:"c25", title:"Application Object Deep Dive", titleBn:"অ্যাপ্লিকেশন অবজেক্ট", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Application Scope","content":"Application variables accessible by ALL users. Use for site-wide counters, configuration, cached data. Lifetime: app start to app end(IIS restart)."},{"id":"s2","type":"lesson","title":"Concurrency Control","content":"Application.Lock prevents concurrent writes. Application.Unlock releases. Always pair Lock with Unlock. Keep locked duration minimal. Nested locking not required."},{"id":"s3","type":"lesson","title":"Application Events","content":"Application_OnStart(in Global.asa): initialize counters, load config, warm caches. Application_OnEnd: cleanup, log statistics, close resources."},{"id":"s4","type":"quiz","question":"What happens to Application variables on IIS restart?","options":["Persist to disk","Lost","Backed up","Migrated"],"correct":1,"explanation":"Application variables are lost when IIS restarts (stored in memory)."},{"id":"s5","type":"exercise","title":"Site Statistics","description":"Use Application to store page hit counter, active users count, uptime tracker. Display on admin dashboard with Lock/Unlock protection."}] },
  { id:"c26", title:"ASPError Object", titleBn:"ASPError অবজেক্ট", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Getting ASP Error Info","content":"Server.GetLastError returns ASPError object. Use in custom 500 error page. Properties: ASPCode, ASPDescription, Category, File, Line, Column, Description."},{"id":"s2","type":"lesson","title":"Custom Error Pages","content":"IIS config: Error Pages → 500 → Custom path. Create 500-100.asp. Use Server.GetLastError. Display user-friendly message. Log full error details."},{"id":"s3","type":"lesson","title":"Error Logging","content":"Log errors to file(FileSystemObject), database(ADO), or Windows Event Log. Include timestamp, user, page, error details. Email critical errors to admin."},{"id":"s4","type":"quiz","question":"Which object provides detailed error info?","options":["Err","ASPError","ErrorInfo","Exception"],"correct":1,"explanation":"ASPError object from Server.GetLastError provides detailed ASP runtime error info."},{"id":"s5","type":"exercise","title":"Custom Error Handler","description":"Create custom 500 error page. Use Server.GetLastError, display user-friendly message, log full details to file, email admin for critical errors."}] },
  { id:"c27", title:"Response.Flush and Buffering", titleBn:"রেসপন্স বাফারিং", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Output Buffering","content":"Response.Buffer=True(default in IIS 6+). Entire page processed before sending. Pro: can use Redirect anywhere. Con: user waits for full processing."},{"id":"s2","type":"lesson","title":"Progressive Rendering","content":"Response.Buffer=False streams as processed. Response.Flush sends current buffer periodically. Useful for long operations. Check IsClientConnected before Flush."},{"id":"s3","type":"lesson","title":"Buffer Management","content":"Response.Clear discards buffer. Response.SuppressContent suppresses all output. Response.Flush sends buffer. Response.End stops processing."},{"id":"s4","type":"quiz","question":"Which method sends current buffer to client?","options":["End","Flush","Clear","BinaryWrite"],"correct":1,"explanation":"Response.Flush sends the current buffer contents to the client."},{"id":"s5","type":"exercise","title":"Progressive Page","description":"Create page that processes 10 steps, using Flush between each step, check IsClientConnected, show progress indicator, allow cancellation."}] },
  { id:"c28", title:"Content Linking and Rotation", titleBn:"কন্টেন্ট লিঙ্কিং", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Content Linking Component","content":"CreateObject(\"MSWC.NextLink\"). Manages linear navigation through URL lists from a text file. Methods: GetNextURL, GetPreviousURL, GetListIndex, GetNthURL."},{"id":"s2","type":"lesson","title":"Content Rotator Component","content":"CreateObject(\"MSWC.ContentRotator\"). Rotates content snippets(advertisements, tips). Content schedule file with weighted entries. ChooseContent method returns random entry."},{"id":"s3","type":"lesson","title":"Page Counter Component","content":"CreateObject(\"MSWC.PageCounter”). Tracks page hits. Methods: Hits(page), Hits, PageHit, Reset(page). Store in Central_Control.ini file."},{"id":"s4","type":"quiz","question":"Which component rotates advertisements?","options":["NextLink","ContentRotator","PageCounter","AdRotator"],"correct":3,"explanation":"Wait, the answer should be ContentRotator (MSWC.ContentRotator). AdRotator is MSWC.AdRotator."},{"id":"s5","type":"exercise","title":"Content Management","description":"Use ContentRotator to display rotating tips on homepage. Use NextLink for tutorial navigation. Use PageCounter to display popular pages."}] },
  { id:"c29", title:"Browser Capabilities", titleBn:"ব্রাউজার ক্যাপাবিলিটি", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Browser Capabilities Component","content":"CreateObject(\"MSWC.BrowserType\"). Reads browscap.ini to determine browser features. Properties: Browser, Version, Frames, Tables, Cookies, JavaScript, VBScript, ActiveXControls."},{"id":"s2","type":"lesson","title":"Feature Detection","content":"Check capabilities before using features. If bc.JavaScript Then use JS: Else degrade gracefully. If bc.ActiveXControls = \"True\" Then use ActiveX component."},{"id":"s3","type":"lesson","title":"Customizing Content","content":"Serve different content based on browser: mobile vs desktop, HTML5 vs legacy, specific browser quirks. Maintenance heavy—use progressive enhancement."},{"id":"s4","type":"quiz","question":"What file does Browser Capabilities read?","options":["browscap.ini","browser.xml","capabilities.ini","useragent.txt"],"correct":0,"explanation":"MSWC.BrowserType reads browscap.ini to determine browser capabilities."},{"id":"s5","type":"exercise","title":"Browser Detection","description":"Use Browser Capabilities component to detect browser name/version, display appropriate content, and show feature support table."}] },
  { id:"c30", title:"ASP and COM+ Transactions", titleBn:"এএসপি এবং কম+ ট্রানজেকশন", part:"ASP Built-in Objects", sections:[{"id":"s1","type":"lesson","title":"Transaction Processing","content":"@Transaction=Required directive makes page transactional. Uses MTS/COM+ transaction services. Rollback on error: ObjectContext.SetAbort. Commit: SetComplete."},{"id":"s2","type":"lesson","title":"ObjectContext Object","content":"Created automatically for transactional pages. Methods: SetComplete(commit), SetAbort(rollback). Events: OnTransactionCommit, OnTransactionAbort."},{"id":"s3","type":"lesson","title":"Database Transactions","content":"Use ADO Connection.BeginTrans/CommitTrans/RollbackTrans. Combine with ASP transactions for distributed transactions across multiple databases or components."},{"id":"s4","type":"quiz","question":"Which method rolls back a transaction?","options":["SetComplete","SetAbort","CommitTrans","RollbackTrans"],"correct":1,"explanation":"SetAbort rolls back the COM+ transaction for the ASP page."},{"id":"s5","type":"exercise","title":"Bank Transfer Transaction","description":"Create fund transfer page: debit account A, credit account B. Use COM+ transaction so both succeed or both roll back on error."}] },
  { id:"c31", title:"ADO Connection Pooling", titleBn:"এডিও কানেকশন পুলিং", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"Connection Pooling","content":"IIS automatically pools OLEDB/ODBC connections. Connection strings with same properties share pool. Pool keeps connections alive for reuse."},{"id":"s2","type":"lesson","title":"Pool Configuration","content":"Connection string: \"Pooling=True;Min Pool Size=5;Max Pool Size=100;Connection Lifetime=300\". Monitor pool with Performance Monitor counters."},{"id":"s3","type":"lesson","title":"Best Practices","content":"Always close connections(return to pool). Keep Min Pool Size for warm start. Max Pool Size prevents resource exhaustion. Connection Lifetime for load balancing."},{"id":"s4","type":"quiz","question":"What happens when pool is exhausted?","options":["New connection created","Error returned","Request queued","Oldest connection reused"],"correct":1,"explanation":"Error \"Connection pool timeout\" returned when max pool size exceeded."},{"id":"s5","type":"exercise","title":"Pool Monitor","description":"Write ASP page that queries SQL Server performance counters, display pool statistics: active, idle, max connections, and connection timeouts."}] },
  { id:"c32", title:"ADO Command Object", titleBn:"এডিও কমান্ড অবজেক্ট", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"Command Object Overview","content":"CreateObject(\"ADODB.Command\"). Provides parameterized queries and stored procedure execution. Properties: CommandText, CommandType, ActiveConnection, CommandTimeout."},{"id":"s2","type":"lesson","title":"Parameters Collection","content":"cmd.Parameters.Append cmd.CreateParameter(\"@name\", adVarChar, adParamInput, 50, value). Parameter directions: Input, Output, InputOutput, ReturnValue."},{"id":"s3","type":"lesson","title":"Stored Procedures","content":"Set cmd.CommandType = adCmdStoredProc(4). cmd.CommandText = \"usp_GetProduct\". Execute with parameters. Get return value from Parameters(\"@RETURN_VALUE\")."},{"id":"s4","type":"quiz","question":"Which CommandType is for stored procedures?","options":["adCmdText","adCmdTable","adCmdStoredProc","adCmdUnknown"],"correct":2,"explanation":"adCmdStoredProc(4) tells ADO the CommandText is a stored procedure name."},{"id":"s5","type":"exercise","title":"Stored Procedure Execution","description":"Create SQL stored procedures for CRUD on Products table. Execute from ASP using Command object with input/output parameters."}] },
  { id:"c33", title:"Advanced Recordset Operations", titleBn:"উন্নত রেকর্ডসেট অপারেশন", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"Cursor Types","content":"adOpenForwardOnly(0,fastest,default), adOpenKeyset(1,scrollable), adOpenDynamic(2,see changes), adOpenStatic(3,snapshot). Choose based on needs."},{"id":"s2","type":"lesson","title":"Lock Types","content":"adLockReadOnly(1,default), adLockPessimistic(2,lock on edit), adLockOptimistic(3,lock on update), adLockBatchOptimistic(4,batch updates)."},{"id":"s3","type":"lesson","title":"Batch Updates","content":"Open with adLockBatchOptimistic. Modify records. rs.UpdateBatch applies all changes. rs.CancelBatch discards. rs.Status shows pending status."},{"id":"s4","type":"quiz","question":"Which lock type is for batch updates?","options":["adLockReadOnly","adLockPessimistic","adLockOptimistic","adLockBatchOptimistic"],"correct":3,"explanation":"adLockBatchOptimistic enables batch updates with UpdateBatch method."},{"id":"s5","type":"exercise","title":"Batch Update Example","description":"Open Recordset in batch mode, modify multiple records, display pending changes, then UpdateBatch or CancelBatch based on user confirmation."}] },
  { id:"c34", title:"SQL Injection Prevention", titleBn:"এসকিউএল ইনজেকশন প্রতিরোধ", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"Understanding SQL Injection","content":"Attacker injects SQL via user input. Example: ' OR '1'='1 bypasses authentication. '; DROP TABLE Users;-- deletes tables. Always dangerous."},{"id":"s2","type":"lesson","title":"Parameterized Queries","content":"Use Command object with Parameters. Never concatenate user input into SQL. Parameterized queries separate SQL from data—input treated as literal only."},{"id":"s3","type":"lesson","title":"Input Validation","content":"Validate type: IsNumeric, IsDate. Validate length: Len(input) < max. Whitelist patterns with regex. Use Server.HTMLEncode for output. Second line of defense."},{"id":"s4","type":"quiz","question":"Which is most effective against SQL injection?","options":["Input validation","Parameterized queries","Stored procedures","HTML encoding"],"correct":1,"explanation":"Parameterized queries ensure user input is never executed as SQL code."},{"id":"s5","type":"exercise","title":"Secure Login","description":"Create secure login page. Vulnerable version concatenates input. Then rewrite with parameterized query. Demonstrate difference by attempting injection."}] },
  { id:"c35", title:"Displaying Data with Charts", titleBn:"চার্ট দিয়ে ডেটা প্রদর্শন", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"Server-Generated Charts","content":"Use Office Web Components(OWC) Chart: CreateObject(\"OWC11.ChartSpace\"). Set data from Recordset. Customize type, colors, labels. Export as image."},{"id":"s2","type":"lesson","title":"Chart Types","content":"Column, Bar, Line, Pie, Doughnut, Area, Scatter. Choose based on data: Pie for proportions, Line for trends, Bar for comparisons, Column for categories."},{"id":"s3","type":"lesson","title":"Exporting to Excel","content":"Set ContentType=\"application/vnd.ms-excel\". Create HTML table with spreadsheet formatting. Use tab-delimited for simple data export. OWC for formatted Excel."},{"id":"s4","type":"quiz","question":"Which chart type best shows trends over time?","options":["Pie","Bar","Line","Doughnut"],"correct":2,"explanation":"Line charts best display trends and patterns over time periods."},{"id":"s5","type":"exercise","title":"Sales Dashboard","description":"Query monthly sales data from database. Display as bar chart. Show pie chart by product category. Add export to Excel button."}] },
  { id:"c36", title:"Paging and Sorting", titleBn:"পৃষ্ঠা ও সাজানো", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"Server-Side Paging","content":"Use SQL OFFSET-FETCH or TOP-ROW_NUMBER. Pass page number via QueryString. Calculate offset: (page-1)*pageSize. Display page numbers."},{"id":"s2","type":"lesson","title":"Sorting","content":"Use column name from QueryString in ORDER BY. Validate column against whitelist. Toggle ASC/DESC. Display sort indicators(▲/▼) on column headers."},{"id":"s3","type":"lesson","title":"Search with Paging","content":"Combine WHERE with paging: search keyword, page number, sort column/order. Build parameterized query dynamically. Preserve search state across pages."},{"id":"s4","type":"quiz","question":"How is SQL offset calculated?","options":["page*size","(page-1)*pageSize","pageSize/page","page+pageSize"],"correct":1,"explanation":"Offset = (pageNumber-1) * pageSize skips previous pages' records."},{"id":"s5","type":"exercise","title":"Data Grid","description":"Build sortable, pageable data grid: 50+ record dataset, column headers click to sort, page navigation, records-per-page selector, search filter."}] },
  { id:"c37", title:"Working with XML Data", titleBn:"এক্সএমএল ডেটার সাথে কাজ", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"Recordset to XML","content":"rs.Save Response, adPersistXML(1). Converts Recordset to XML format. Includes schema. Load with rs.Open XML string. Portable data format."},{"id":"s2","type":"lesson","title":"XSLT Transformations","content":"Load XML into DOMDocument. Load XSL stylesheet. Transform: xmlDoc.transformNode(xslDoc). Outputs HTML. Separates data from presentation."},{"id":"s3","type":"lesson","title":"RSS Feeds","content":"Build RSS 2.0 feed from database. Set ContentType=\"text/xml\". Use XSLT for browser formatting. Implement caching(Application). Serve latest items."},{"id":"s4","type":"quiz","question":"Which method saves Recordset as XML?","options":["Save","Write","Persist","Export"],"correct":0,"explanation":"rs.Save Response, adPersistXML saves Recordset as XML to Response stream."},{"id":"s5","type":"exercise","title":"Dynamic RSS Feed","description":"Query blog posts from database, generate RSS 2.0 XML, add XSLT stylesheet for browser display, cache output with Application variables."}] },
  { id:"c38", title:"Database Design for ASP", titleBn:"এএসপির জন্য ডেটাবেস ডিজাইন", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"Normalization","content":"1NF(atomic columns), 2NF(no partial dependencies), 3NF(no transitive dependencies). Reduces redundancy. Improves data integrity. Example: split Customers and Orders."},{"id":"s2","type":"lesson","title":"Primary Keys and Indexes","content":"Surrogate keys(IDENTITY auto-increment) vs natural keys(SSN, Email). Clustered index(physical order) on PK. Non-clustered indexes on search columns."},{"id":"s3","type":"lesson","title":"Relationships","content":"One-to-Many(Customer→Orders), Many-to-Many(Students↔Courses via junction table), One-to-One(Employee↔EmployeeDetails). Foreign keys enforce referential integrity."},{"id":"s4","type":"quiz","question":"Which eliminates transitive dependencies?","options":["1NF","2NF","3NF","BCNF"],"correct":2,"explanation":"3NF eliminates transitive dependencies(non-key depends on another non-key)."},{"id":"s5","type":"exercise","title":"Design Database","description":"Design schema for e-commerce: Customers, Orders, OrderItems, Products, Categories. Create tables with proper keys, indexes, and foreign key constraints."}] },
  { id:"c39", title:"ASP and SQL Server", titleBn:"এএসপি এবং এসকিউএল সার্ভার", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"SQL Server Connection","content":"Provider=SQLOLEDB;Data Source=server;Initial Catalog=db;Integrated Security=SSPI; or User ID=...;Password=.... Use trusted connection for security."},{"id":"s2","type":"lesson","title":"SQL Server Features","content":"Views(reusable queries), Stored Procedures(precompiled), Functions(scalar/table-valued), Triggers(after insert/update/delete), Full-Text Search."},{"id":"s3","type":"lesson","title":"T-SQL for ASP Programmers","content":"SELECT with JOINs, INSERT/UPDATE/DELETE, transactions(BEGIN TRAN/COMMIT/ROLLBACK), temp tables(#temp), CTEs, window functions(ROW_NUMBER)."},{"id":"s4","type":"quiz","question":"Which provides parameterized query execution?","options":["EXEC","sp_executesql","SELECT","UPDATE"],"correct":1,"explanation":"sp_executesql supports parameterized execution, preventing SQL injection."},{"id":"s5","type":"exercise","title":"SQL Server Integration","description":"Create stored procedures for product CRUD, use full-text search for product search, implement view for order summaries, use trigger for audit logging."}] },
  { id:"c40", title:"ASP and Access", titleBn:"এএসপি এবং অ্যাক্সেস", part:"Database & ADO", sections:[{"id":"s1","type":"lesson","title":"Access Connection","content":"Provider=Microsoft.Jet.OLEDB.4.0;Data Source=path\\db.mdb; or Microsoft.ACE.OLEDB.12.0 for .accdb. File-based database, single-user by design."},{"id":"s2","type":"lesson","title":"Access Limitations","content":"No stored procedures(only queries), limited concurrent users(~25), 2GB file size limit, file-based locking. Suitable for small sites. Migrate to SQL Server for growth."},{"id":"s3","type":"lesson","title":"Migration to SQL Server","content":"UPSizing Wizard, DTS package, or manual. Convert queries to views/stored procs. Handle differences: IIF→CASE, DateDiff syntax, LIKE patterns."},{"id":"s4","type":"quiz","question":"What is max file size for Access?","options":["1GB","2GB","4GB","10GB"],"correct":1,"explanation":"Access database file(.mdb/.accdb) has a 2GB maximum size limit."},{"id":"s5","type":"exercise","title":"Access Migration","description":"Connect ASP to Access database, perform CRUD operations, then create SQL Server version with same schema. Document differences in queries and syntax."}] },
  { id:"c41", title:"Advanced Form Techniques", titleBn:"উন্নত ফর্ম টেকনিক", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"Multi-Step Forms","content":"Use hidden field CurrentStep to track progress. Validate each step. Store data in Session. Display step indicator. Review step before final submission."},{"id":"s2","type":"lesson","title":"Form Data Persistence","content":"Keep form values after submission: value=\"<%= Server.HTMLEncode(Request.Form(\"field\")) %>\". Error messages next to fields. Highlight invalid fields."},{"id":"s3","type":"lesson","title":"AJAX Form Submission","content":"Use XMLHttpRequest for async form submission. Return JSON from ASP: Response.ContentType=\"application/json\". Parse and display server response."},{"id":"s4","type":"quiz","question":"How are multi-step form values maintained?","options":["Cookies","Session","Database","Hidden fields"],"correct":1,"explanation":"Session variables store multi-step form data between steps."},{"id":"s5","type":"exercise","title":"Multi-Step Registration","description":"Build registration wizard: step1(personal info), step2(address), step3(preferences), step4(review). Validate each step, store in Session, submit at end."}] },
  { id:"c42", title:"Authentication Systems", titleBn:"অথেনটিকেশন সিস্টেম", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"Basic Authentication","content":"IIS built-in. Sends Base64 encoded credentials. Enable on directory. Requires HTTPS. No login page needed. Minimal customization. Works with all browsers."},{"id":"s2","type":"lesson","title":"Form-Based Authentication","content":"Custom login page. Validate credentials against database. Set Session(\"UserID\") and Session(\"Role\") on success. Check on every protected page."},{"id":"s3","type":"lesson","title":"Integrated Windows Auth","content":"Uses NTLM or Kerberos. Transparent authentication within domain. Enable in IIS(Windows Authentication). REMOTE_USER server variable has username. Intranet only."},{"id":"s4","type":"quiz","question":"Which authentication requires HTTPS?","options":["Basic","Forms","Windows","Anonymous"],"correct":0,"explanation":"Basic Authentication sends Base64 credentials—easily decoded without HTTPS."},{"id":"s5","type":"exercise","title":"Secure Authentication","description":"Build login system with session management, password hashing, brute force protection(account lockout after 5 failures), remember-me cookie."}] },
  { id:"c43", title:"Authorization and Roles", titleBn:"অথরাইজেশন এবং রোল", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"Role-Based Access","content":"Store user roles in database(table: Users-Roles). Check Session(\"Role\") on page load. Redirect unauthorized users. Show/hide UI elements based on role."},{"id":"s2","type":"lesson","title":"Page-Level Security","content":"Include check page: <!--#include file=\"check_access.asp\"-->. check_access.asp validates Session(\"Role\") against required role. Redirect if unauthorized."},{"id":"s3","type":"lesson","title":"Feature-Level Security","content":"Check permissions within features. Admin can edit/delete, Editor can create/edit, Viewer can read only. Use functions: HasPermission(action, resource)."},{"id":"s4","type":"quiz","question":"What is the order of checks?","options":["Auth then Role","Role then Auth","Parallel","Optional"],"correct":0,"explanation":"First authenticate(who you are), then authorize(what you can do)."},{"id":"s5","type":"exercise","title":"Role Management","description":"Implement roles: Admin, Editor, Viewer. Admin panel: user/role management. Editor: create/edit content. Viewer: read-only. Protect pages accordingly."}] },
  { id:"c44", title:"HTTPS and SSL", titleBn:"এইচটিটিপিএস এবং এসএসএল", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"Enabling HTTPS","content":"Install SSL certificate on IIS. Bind certificate to website on port 443. Force HTTPS: check Request.ServerVariables(\"HTTPS\") = \"on\". Redirect HTTP to HTTPS."},{"id":"s2","type":"lesson","title":"Secure Cookies","content":"Set Secure flag on cookies: Response.Cookies(\"name\").Secure = True. Set HTTPOnly: Response.Cookies(\"name\").HttpOnly = True. Prevents XSS access."},{"id":"s3","type":"lesson","title":"Mixed Content","content":"HTTPS page loading HTTP resources triggers warnings. Ensure all resources(images, CSS, JS, AJAX) use HTTPS. Use protocol-relative URLs://domain.com/style.css)."},{"id":"s4","type":"quiz","question":"How to check if page is HTTPS?","options":["Request.IsSecure","Request.ServerVariables(\"HTTPS\")","Request.Protocol","Server.HTTPS"],"correct":1,"explanation":"Request.ServerVariables(\"HTTPS\") returns \"on\" if SSL/TLS is active."},{"id":"s5","type":"exercise","title":"HTTPS Implementation","description":"Configure IIS for HTTPS, force SSL redirect, implement HSTS header via Response.AddHeader, set secure cookies, verify mixed content elimination."}] },
  { id:"c45", title:"XSS Prevention", titleBn:"এক্সএসএস প্রতিরোধ", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"Understanding XSS","content":"Cross-Site Scripting: attacker injects malicious scripts. Stored XSS(save to DB), Reflected XSS(in URL), DOM-based XSS(client-side). Steals cookies/sessions."},{"id":"s2","type":"lesson","title":"Server-Side Prevention","content":"Server.HTMLEncode all user output. Encode in context: HTML encode for HTML body, URL encode for links, JavaScript encode for script blocks."},{"id":"s3","type":"lesson","title":"Content Security Policy","content":"Response.AddHeader \"Content-Security-Policy\", \"default-src 'self'\". Restricts script sources. Report violations via report-uri. Defense in depth."},{"id":"s4","type":"quiz","question":"Which encodes HTML special characters?","options":["URLEncode","HTMLEncode","Base64","HexEncode"],"correct":1,"explanation":"Server.HTMLEncode converts < > & \" to safe HTML entities."},{"id":"s5","type":"exercise","title":"XSS Protection","description":"Create comment system with XSS vulnerability, demonstrate attack, then fix with HTMLEncode all user output and implement CSP header."}] },
  { id:"c46", title:"CSRF Prevention", titleBn:"সিএসআরএফ প্রতিরোধ", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"Understanding CSRF","content":"Cross-Site Request Forgery: attacker tricks authenticated user into submitting malicious request. Exploits automatic cookies(browser sends session cookie)."},{"id":"s2","type":"lesson","title":"Anti-CSRF Tokens","content":"Generate random token per session: Session(\"CSRFToken\") = CreateGUID(). Include in forms: <input type=\"hidden\" name=\"csrf\" value=\"...\">. Validate on POST."},{"id":"s3","type":"lesson","title":"SameSite Cookies","content":"Set SameSite=Lax or Strict. Lax: cookie sent for top-level GET. Strict: not sent for cross-site requests. Modern browser support. Additional protection."},{"id":"s4","type":"quiz","question":"What type of attack is CSRF?","options":["Cookie theft","Session hijacking","Cross-site request","SQL injection"],"correct":2,"explanation":"CSRF tricks user's browser into making unauthorized requests to authenticated site."},{"id":"s5","type":"exercise","title":"CSRF Protection","description":"Build bank transfer form. Implement anti-CSRF token(store in session, validate on POST). Demonstrate attack fails without valid token."}] },
  { id:"c47", title:"File Upload Security", titleBn:"ফাইল আপলোড সুরক্ষা", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"Upload Risks","content":"Malware upload, path traversal, server overload, file execution. Attacker uploads ASP shell → executes commands. Critical security surface."},{"id":"s2","type":"lesson","title":"Validation Checklist","content":"Check file extension(whitelist: jpg,gif,png,pdf). Check MIME type. Check file size(max bytes). Scan with antivirus. Rename file(uploaded_guid.ext)."},{"id":"s3","type":"lesson","title":"Secure Storage","content":"Store outside web root. Use database BLOB or secure folder with No Execute permission. Set proper NTFS permissions. Serve via handler script(not direct URL)."},{"id":"s4","type":"quiz","question":"Best practice for file extension check?","options":["Blacklist","Whitelist","Regex","All"],"correct":1,"explanation":"Whitelist allowed extensions, reject everything else. Blacklists are easily bypassed."},{"id":"s5","type":"exercise","title":"Secure File Upload","description":"Create file upload with: extension whitelist, size limit, server-side MIME check, file rename, store outside web root, show preview for images only."}] },
  { id:"c48", title:"Logging and Auditing", titleBn:"লগিং এবং অডিটিং", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"IIS Logs","content":"Located in %SystemDrive%\\inetpub\\logs\\LogFiles. W3C Extended format: date, time, cs-uri-stem, cs-username, c-ip, sc-status, sc-bytes. Analyze with Log Parser."},{"id":"s2","type":"lesson","title":"Application Logging","content":"Custom logging: write to file(FileSystemObject), database(ADO), or Windows Event Log. Log: timestamp, user, action, IP, page, result, duration."},{"id":"s3","type":"lesson","title":"Audit Trail","content":"Track sensitive operations: logins, data modifications, admin actions, failed attempts. Include before/after values for changes. Non-repudiation. Store securely."},{"id":"s4","type":"quiz","question":"Which IIS log field tracks response status?","options":["cs-uri-stem","c-ip","sc-status","sc-bytes"],"correct":2,"explanation":"sc-status contains HTTP status code(200, 404, 500, etc.) in IIS logs."},{"id":"s5","type":"exercise","title":"Audit System","description":"Build audit logging: log all admin actions to database table. Display audit trail in admin panel with filters(user, action, date range). Allow export."}] },
  { id:"c49", title:"ASP and Web Services", titleBn:"এএসপি এবং ওয়েব সার্ভিস", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"SOAP Web Services","content":"Create SOAP server: receive XML SOAP envelope, process, return XML response. Set ContentType=\"text/xml\". Use MSXML2.DOMDocument for parsing."},{"id":"s2","type":"lesson","title":"REST APIs from ASP","content":"Build RESTful endpoints: GET(Read), POST(Create), PUT(Update), DELETE. Return JSON: Response.ContentType=\"application/json\". Use Dictionary to build JSON."},{"id":"s3","type":"lesson","title":"Consuming Web Services","content":"Use ServerXMLHTTP to call external APIs. Parse XML/JSON response. Handle errors, timeouts, authentication. Cache responses. Example: weather API, payment gateway."},{"id":"s4","type":"quiz","question":"Which format does REST typically use?","options":["XML","JSON","SOAP","HTML"],"correct":1,"explanation":"JSON is the most common data format for RESTful APIs."},{"id":"s5","type":"exercise","title":"REST API Builder","description":"Build REST endpoints for CRUD on Products table. GET/products, GET/products/1, POST/products, PUT/products/1, DELETE/products/1. Return JSON."}] },
  { id:"c50", title:"JSON in ASP", titleBn:"এএসপিতে জেসন", part:"Forms & Security", sections:[{"id":"s1","type":"lesson","title":"Generating JSON","content":"Build string: {\"key\": \"value\"}. Use Dictionary or array iteration. Escape quotes. For arrays: [item1,item2]. For nested objects: {\"inner\": {...}}."},{"id":"s2","type":"lesson","title":"Parsing JSON","content":"Use JSON.parse via Server-Side JScript, or MSXML2 parser, or custom VBScript parser. Newtonsoft JSON library via COM. For simple cases, regex parsing works."},{"id":"s3","type":"lesson","title":"JSON APIs","content":"Serve ASP endpoints returning JSON for AJAX clients. Accept JSON POST data(Request.BinaryRead, parse). ContentType=\"application/json\". CORS headers for cross-origin."},{"id":"s4","type":"quiz","question":"ASP's primary scripting language is VBScript. What is used for JSON parsing?","options":["Built-in","ASPJSON.COM","JScript eval","All of above"],"correct":3,"explanation":"Various approaches work: JScript, COM components, or custom VBScript parser."},{"id":"s5","type":"exercise","title":"JSON Endpoints","description":"Create ASP endpoint returning JSON array of products. Create client-side JavaScript that fetches and displays the data. Add CORS header for cross-domain access."}] },
  { id:"c51", title:"Performance Monitoring", titleBn:"পারফরম্যান্স মনিটরিং", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"ASP Performance Counters","content":"Windows Performance Monitor: ASP counters(Requests Current, Requests Queued, Requests Rejected, Sessions Current, Errors Total, Script Engines Cached)."},{"id":"s2","type":"lesson","title":"Common Bottlenecks","content":"Slow database queries(low-hanging fruit). Excessive Session variables. Missing indexes. No caching. Large ViewState. COM object leaks. Memory fragmentation."},{"id":"s3","type":"lesson","title":"Profiling ASP Pages","content":"Track page execution: start=Timer. End: duration=Timer-start. Log slow pages(>1s). Check with Response.IsClientConnected. Profile database queries separately."},{"id":"s4","type":"quiz","question":"Which counter shows waiting requests?","options":["Requests Current","Requests Queued","Requests Rejected","Sessions Current"],"correct":1,"explanation":"Requests Queued shows ASP requests waiting for processing."},{"id":"s5","type":"exercise","title":"Performance Dashboard","description":"Build admin page showing ASP performance counters, slowest pages(from log), cache hit ratios, database query times, and connection pool stats."}] },
  { id:"c52", title:"Caching Strategies", titleBn:"ক্যাশিং কৌশল", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"Output Caching","content":"Response.CacheControl=\"public\" or \"private\". Response.Expires=60(cache 1 minute). Response.AddHeader \"Last-Modified\", lastModDate. Conditional GET with If-Modified-Since."},{"id":"s2","type":"lesson","title":"Data Caching","content":"Cache database results in Application Dictionary. Check timestamp: If cache older than X minutes, refresh. Cache frequently accessed, rarely changed data."},{"id":"s3","type":"lesson","title":"Fragment Caching","content":"Cache parts of page using Server.Execute(cached output). Generate cached snippets as .asp files with Server.Execute. Invalidate cache when source data changes."},{"id":"s4","type":"quiz","question":"Which pattern caches parts of page?","options":["Output caching","Data caching","Fragment caching","Full page caching"],"correct":2,"explanation":"Fragment caching caches portions of a page while keeping other parts dynamic."},{"id":"s5","type":"exercise","title":"Implement Caching","description":"Cache product categories in Application(a 5-minute refresh). Implement output caching for product listing page. Add fragment cache for navigation menu."}] },
  { id:"c53", title:"Load Balancing Considerations", titleBn:"লোড ব্যালেন্সিং", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"Session Affinity","content":"Sticky sessions: all requests from user go to same server. Required for In-Process session. Configure load balancer with source IP hash or cookie."},{"id":"s2","type":"lesson","title":"Stateless Design","content":"Move session out-of-process(StateServer or SQLServer). Avoid Application variables(per-server). Use database for shared state. Cache database behind load balancer."},{"id":"s3","type":"lesson","title":"Shared Resources","content":"Centralized file storage(UNC path or DFS). Application connection strings in shared config. Shared logging. Distributed caching(Memcached/Redis via COM)."},{"id":"s4","type":"quiz","question":"What does sticky session ensure?","options":["Same server","Fast response","Load balance","High availability"],"correct":0,"explanation":"Sticky session(affinity) ensures user stays on same server for session continuity."},{"id":"s5","type":"exercise","title":"Web Farm Design","description":"Design architecture for 3-server web farm: shared session state, centralized files, database connection pooling, shared caching, and monitoring strategy."}] },
  { id:"c54", title:"Migrating Classic ASP to ASP.NET", titleBn:"ক্লাসিক এএসপি থেকে এএসপি.নেট", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"Migration Planning","content":"Inventory all ASP pages, COM components, database calls, session usage. Choose approach: full rewrite, side-by-side(IIS 6+ supports both), or phased migration."},{"id":"s2","type":"lesson","title":"Key Differences","content":"Code-behind vs inline. Compiled vs interpreted. Strong typing vs Variant. Events vs linear processing. ViewState vs form state management."},{"id":"s3","type":"lesson","title":"Migration Strategies","content":"Rewrite core business logic first. Use Interop for COM components. Share session state with ASP.NET sessions. Incremental migration with IIS path mapping."},{"id":"s4","type":"quiz","question":"Which approach runs both ASP and ASP.NET?","options":["Rewrite","Side-by-side","Phased","Container"],"correct":1,"explanation":"IIS supports running Classic ASP and ASP.NET on same server with different extensions."},{"id":"s5","type":"exercise","title":"Migration Plan","description":"Create migration plan for sample app: identify all ASP pages, categorize complexity, propose ASP.NET equivalents, estimate effort, create timeline."}] },
  { id:"c55", title:"Debugging ASP Applications", titleBn:"এএসপি ডিবাগিং", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"Server-Side Debugging","content":"Response.Write for variable inspection. Include debug info: show Session, Application, Request collections in HTML comments. Use Response.End to stop at breakpoint."},{"id":"s2","type":"lesson","title":"IIS Debugging Tools","content":"Failed Request Tracing(IIS 7+): configure trace rules for specific status codes(500). View trace XML in browser. Shows execution flow and errors."},{"id":"s3","type":"lesson","title":"Debugging COM Components","content":"Use Component Services to monitor COM+ activity. Enable component tracking. Check identity and permissions. DumpViewer for state. Windows Debugger for crashes."},{"id":"s4","type":"quiz","question":"Which IIS feature traces failed requests?","options":["Failed Request Tracing","Debug Mode","Trace Viewer","Error Logging"],"correct":0,"explanation":"Failed Request Tracing(IIS 7+) captures detailed execution trace for problematic requests."},{"id":"s5","type":"exercise","title":"Debug Practice","description":"Introduce bugs into ASP page(typo, SQL error, logic error), use Response.Write debugging, enable Failed Request Tracing, fix all bugs."}] },
  { id:"c56", title:"ASP and Third-Party APIs", titleBn:"এএসপি এবং থার্ড-পার্টি এপিআই", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"Payment Gateway Integration","content":"ServerXMLHTTP to call payment API(Stripe, PayPal). Send order details. Receive transaction ID. Handle success/failure responses. Never log credit card data."},{"id":"s2","type":"lesson","title":"Social Media APIs","content":"Facebook Graph API: authenticate with OAuth, get user data, post to timeline. REST endpoints with JSON responses. Access tokens for authentication."},{"id":"s3","type":"lesson","title":"Mapping and Geolocation","content":"Google Maps API via JavaScript(client-side) or geocoding API(server-side). Store coordinates in database. Calculate distances. Display maps with markers."},{"id":"s4","type":"quiz","question":"Which HTTP method authenticates with OAuth?","options":["POST credentials","Access token","API key","Certificate"],"correct":1,"explanation":"OAuth 2.0 uses access tokens(sent as Bearer header) for API authentication."},{"id":"s5","type":"exercise","title":"API Integration","description":"Integrate a weather API: retrieve JSON forecast, parse and display. Add payment gateway mock: send order, receive confirmation. Handle API errors gracefully."}] },
  { id:"c57", title:"Responsive Design with ASP", titleBn:"এএসপির সাথে রেসপন্সিভ ডিজাইন", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"Dynamic CSS","content":"Serve device-specific CSS: check User-Agent for mobile/tablet/desktop. Serve different CSS files. Use media queries for responsive same-CSS approach."},{"id":"s2","type":"lesson","title":"Mobile Detection","content":"Check Request.ServerVariables(\"HTTP_USER_AGENT\") for mobile keywords. Use browser capabilities component. Redirect to mobile subdomain or serve different template."},{"id":"s3","type":"lesson","title":"Template Switching","content":"Different templates for different devices. Include header_mobile.asp or header_desktop.asp. Use CSS framework(Bootstrap) for single template approach."},{"id":"s4","type":"quiz","question":"Which approach is best for responsive design?","options":["Separate mobile site","CSS media queries","User agent detection","Template switching"],"correct":1,"explanation":"CSS media queries provide responsive design without device detection or redirects."},{"id":"s5","type":"exercise","title":"Responsive Site","description":"Create ASP page that detects mobile users and serves appropriate CSS. Use CSS media queries for responsive layout. Test with different viewport sizes."}] },
  { id:"c58", title:"ASP and SEO", titleBn:"এএসপি এবং সার্চ ইঞ্জিন অপ্টিমাইজেশন", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"SEO-Friendly URLs","content":"URL rewriting with IIS URL Rewrite Module. Convert product.asp?id=1 to /product/1/awesome-product. Pattern-based rules. SEO benefits: keywords in URL."},{"id":"s2","type":"lesson","title":"Meta Tags Dynamic Generation","content":"Set meta description, keywords, title from database per page. Response.Write \"<meta name='description' content='\" & metaDescription & \"'>\". Open Graph tags for social sharing."},{"id":"s3","type":"lesson","title":"Sitemap Generation","content":"Dynamic XML sitemap: query all pages/URLs, output XML with priority and changefreq. Set ContentType=\"text/xml\". Submit to Google Search Console. Robots.txt."},{"id":"s4","type":"quiz","question":"Which IIS feature enables friendly URLs?","options":["Rewrite Module","Routing","URL Rewrite","SEO Module"],"correct":2,"explanation":"IIS URL Rewrite Module creates search-engine-friendly URLs from dynamic ones."},{"id":"s5","type":"exercise","title":"SEO Implementation","description":"Implement URL Rewrite rules for product/category pages. Generate dynamic sitemap.xml. Add meta tags per page. Create robots.txt. Verify with SEO tools."}] },
  { id:"c59", title:"ASP Maintenance and Troubleshooting", titleBn:"এএসপি রক্ষণাবেক্ষণ", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"Common IIS Issues","content":"404(handler mapping missing), 500(script error), 401(authentication), 503(server overload). Check IIS logs. Enable detailed errors for development. "},{"id":"s2","type":"lesson","title":"Database Connectivity Issues","content":"Connection string problems: provider not installed, server unreachable, credentials invalid, database offline, network firewall blocking port."},{"id":"s3","type":"lesson","title":"COM Component Registration","content":"Regsvr32 for reg/unreg. 32-bit vs 64-bit mismatch common. Dependency Walker for missing DLLs. DCOMCNFG for permissions. Event Viewer for errors."},{"id":"s4","type":"quiz","question":"HTTPS 500 error usually indicates?","options":["Server overload","Script error","Auth failure","File not found"],"correct":1,"explanation":"HTTP 500 is a generic server error, usually from ASP script errors or IIS configuration."},{"id":"s5","type":"exercise","title":"Troubleshooting Guide","description":"Create diagnostic ASP page: test COM components, database connection, file permissions, server variables. Write troubleshooting checklist for common issues."}] },
  { id:"c60", title:"Future of Classic ASP", titleBn:"ক্লাসিক এএসপির ভবিষ্যৎ", part:"Advanced ASP Topics", sections:[{"id":"s1","type":"lesson","title":"ASP Today","content":"ASP runs on IIS 7-10(Windows 10/11, Server 2016-2022). Still used in enterprise legacy apps. Microsoft continues support but no new features. Large installed base."},{"id":"s2","type":"lesson","title":"Modern Alternatives","content":"ASP.NET Core(cross-platform), PHP(open source, widely hosted), Python Flask/Django, Node.js/Express. Choose based on team skills, ecosystem, performance needs."},{"id":"s3","type":"lesson","title":"Career Relevance","content":"ASP developers in demand for maintenance/ migration projects. Skills transfer: VBScript→VB.NET, ASP→ASP.NET MVC. Understanding ASP fundamentals helps all web development."},{"id":"s4","type":"quiz","question":"Is Classic ASP still supported on Windows Server 2022?","options":["Yes","No","Limited","Deprecated"],"correct":0,"explanation":"Classic ASP remains supported on all modern Windows/IIS versions including Server 2022."},{"id":"s5","type":"exercise","title":"Legacy Modernization","description":"Audit an existing ASP app, identify components for migration, present modernization roadmap with technology recommendations and effort estimates."}] }
  ]
};